```ts
// /tmp/legion-35-probe/probe.ts — throwaway. Can Bun reach flock(2) through bun:ffi, is errno
// readable after a failed call, and are node:fs descriptors inherited by spawned children?
import { spawn as nodeSpawn } from "node:child_process";
import fs from "node:fs";
import { readdirSync, readlinkSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { dlopen, FFIType, read as ffiRead, type Pointer } from "bun:ffi";

const LOCK_EX = 2;
const LOCK_NB = 4;
const EWOULDBLOCK = 11;
const EBADF = 9;
const results: Record<string, unknown> = {};

const libc = dlopen("libc.so.6", {
  flock: { args: [FFIType.i32, FFIType.i32], returns: FFIType.i32 },
  __errno_location: { args: [], returns: FFIType.ptr },
});
results.dlopen = "ok";
const errno = () => ffiRead.i32(libc.symbols.__errno_location() as Pointer, 0);

const dir = fs.mkdtempSync(path.join(os.tmpdir(), "legion-35-probe-"));
const lockFile = path.join(dir, "daemon.lock");
const flags = fs.constants.O_RDWR | fs.constants.O_CREAT | 0o2000000; // O_CLOEXEC: fs.constants lacks it under Bun
results.O_CLOEXEC_constant = String(fs.constants.O_CLOEXEC);

const fd1 = fs.openSync(lockFile, flags, 0o644);
const fd2 = fs.openSync(lockFile, flags, 0o644);
results.firstFlock = libc.symbols.flock(fd1, LOCK_EX | LOCK_NB);
const r2 = libc.symbols.flock(fd2, LOCK_EX | LOCK_NB);
const e2 = errno();
results.secondFlockWhileHeld = { rc: r2, errno: e2, isEWOULDBLOCK: e2 === EWOULDBLOCK };
const fdinfo = fs.readFileSync(`/proc/self/fdinfo/${fd1}`, "utf8");
results.fd1FlagsOctal = /flags:\s+(\d+)/.exec(fdinfo)?.[1];
fs.closeSync(fd1);
results.secondFlockAfterFirstClosed = libc.symbols.flock(fd2, LOCK_EX | LOCK_NB);

const r4 = libc.symbols.flock(fd1, LOCK_EX | LOCK_NB);
const e4 = errno();
results.flockClosedFd = { rc: r4, errno: e4, isEBADF: e4 === EBADF };

function childHasLockFd(pid: number): boolean {
  return readdirSync(`/proc/${pid}/fd`).some((n) => {
    try {
      return readlinkSync(`/proc/${pid}/fd/${n}`) === lockFile;
    } catch {
      return false;
    }
  });
}
const bunChild = Bun.spawn(["sleep", "30"], { stdout: "ignore", stderr: "ignore" });
await Bun.sleep(100);
results.bunSpawnChildInherited = childHasLockFd(bunChild.pid);
bunChild.kill();
const nodeChild = nodeSpawn("sleep", ["30"], { stdio: "ignore" });
await Bun.sleep(100);
results.nodeSpawnChildInherited = childHasLockFd(nodeChild.pid as number);
nodeChild.kill();
fs.closeSync(fd2);

const holderSrc = `
import fs from "node:fs";
import { dlopen, FFIType } from "bun:ffi";
const libc = dlopen("libc.so.6", { flock: { args: [FFIType.i32, FFIType.i32], returns: FFIType.i32 } });
const fd = fs.openSync(process.argv[2], fs.constants.O_RDWR | fs.constants.O_CREAT | 0o2000000, 0o644);
if (libc.symbols.flock(fd, 6) !== 0) { console.log("holder-flock-failed"); process.exit(2); }
fs.ftruncateSync(fd, 0); fs.writeSync(fd, String(process.pid), 0);
console.log("locked");
setInterval(() => {}, 1000);
`;
const holderPath = path.join(dir, "holder.ts");
fs.writeFileSync(holderPath, holderSrc);
const holder = Bun.spawn([process.execPath, holderPath, lockFile], { stdout: "pipe", stderr: "inherit" });
const { value } = await holder.stdout.getReader().read();
results.holderSaid = new TextDecoder().decode(value).trim();
const fd5 = fs.openSync(lockFile, flags, 0o644);
const r5 = libc.symbols.flock(fd5, LOCK_EX | LOCK_NB);
results.parentFlockWhileChildHolds = { rc: r5, errno: errno(), pidText: fs.readFileSync(lockFile, "utf8") };
holder.kill("SIGKILL");
await holder.exited;
results.parentFlockAfterChildKilled = libc.symbols.flock(fd5, LOCK_EX | LOCK_NB);
fs.closeSync(fd5);

const ino0 = fs.statSync(lockFile).ino;
for (let i = 0; i < 5; i += 1) {
  const f = fs.openSync(lockFile, flags, 0o644);
  libc.symbols.flock(f, LOCK_EX | LOCK_NB);
  fs.ftruncateSync(f, 0);
  fs.writeSync(f, String(process.pid), 0);
  fs.closeSync(f);
}
results.inodeStable = fs.statSync(lockFile).ino === ino0;
fs.rmSync(dir, { recursive: true, force: true });
console.log(JSON.stringify(results, null, 2));
```

